Plan: copy the workbook, sum the Amount column by month from the date rows, and write the July/August totals into B10:B11. Treat a zero total as empty to satisfy the “ignore zero” requirement. Save the updated workbook.

```python
import shutil
import openpyxl
import datetime
import calendar

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

month_sums = {}

for r in range(1, vws.max_row + 1):
    date_val = vws.cell(row=r, column=1).value
    amount_val = vws.cell(row=r, column=2).value

    if isinstance(date_val, datetime.datetime):
        month = date_val.month
    elif isinstance(date_val, datetime.date):
        month = date_val.month
    else:
        continue

    if isinstance(amount_val, (int, float)) and not isinstance(amount_val, bool):
        month_sums[month] = month_sums.get(month, 0) + amount_val

month_map = {}
for i, name in enumerate(calendar.month_name):
    if name:
        month_map[name.lower()] = i
for i, name in enumerate(calendar.month_abbr):
    if name:
        month_map[name.lower()] = i

for r in range(10, 12):
    label = ws.cell(row=r, column=1).value

    if label is None:
        ws.cell(row=r, column=2).value = None
        continue

    key = str(label).strip().lower()
    month = month_map.get(key)

    if month is None:
        try:
            month = datetime.datetime.strptime(str(label).strip(), "%B").month
        except ValueError:
            month = None

    if month is None:
        ws.cell(row=r, column=2).value = None
    else:
        total = month_sums.get(month, 0)
        ws.cell(row=r, column=2).value = None if total == 0 else total

print("month_sums:", month_sums)
print("B10:", ws.cell(row=10, column=2).value)
print("B11:", ws.cell(row=11, column=2).value)

wb.save(OUT)
